249	    /** Each member's cut of the pot (null for a member that is not current). A member with a cut is one current,
250	     *  neither retired nor held on the sheet's today;
251	     *  each such member's cut is the pot times their share divided by the shares of the members with a cut added
252	     *  up, rounded half to even to two decimals (0.00 for any other member, and for every member when none has a
253	     *  cut); the remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut
254	     *  (the latest added on a tie; a member with no cut gets none), or when no cut is non-zero to the last member
255	     *  with a share, so the cuts total exactly the pot. */
256	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
257	        List<Boolean> withCut = new ArrayList<>();
258	        BigDecimal shares = BigDecimal.ZERO;
259	        for (PoolMember m : members) {
260	            boolean has = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
261	            withCut.add(has);
262	            if (has) shares = shares.add(new BigDecimal(m.share()));
263	        }
264	        List<BigDecimal> cuts = new ArrayList<>();
265	        int smallest = -1;
266	        int lastWithShare = -1;
267	        BigDecimal sum = BigDecimal.ZERO;
268	        for (int i = 0; i < members.size(); i++) {
269	            PoolMember m = members.get(i);
270	            boolean has = withCut.get(i) && shares.signum() > 0;
271	            BigDecimal share = has ? new BigDecimal(m.share()) : BigDecimal.ZERO;
272	            BigDecimal cut = has ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
273	                    : BigDecimal.ZERO.setScale(2);
274	            cuts.add(cut);
275	            sum = sum.add(cut);
276	            if (has && share.signum() > 0) lastWithShare = i;
277	            if (has && cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
278	                smallest = i;
279	            }
280	        }
281	        int to = smallest >= 0 ? smallest : lastWithShare;
282	        if (to >= 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
283	        List<PoolMember> cut = new ArrayList<>();
284	        for (int i = 0; i < members.size(); i++) {
285	            PoolMember m = members.get(i);
286	            cut.add(new PoolMember(m.personId(), m.pool(), m.name(), m.share(), m.retired(),
287	                    m.current() ? cuts.get(i).setScale(2).toPlainString() : null, m.from(), m.to(), m.current()));
288	        }
289	        return cut;
290	    }
