292	    /** The sheet's pools, by name, each with its members (people and pools) in the order they were added, and
293	     *  their cuts of the pool's pot when the pool is balanced, has a pot and has a current member not retired. A
294	     *  pool's total share counts every current member's share, a retired member's included. A pool that is a member of none has
295	     *  the sheet's pot; a pool that is a member of another has its cut there as its pot (none when that pool
296	     *  shows no cuts). */
297	    public List<Pool> list(String sheetId) {
298	        Map<String, List<PoolMember>> members = new LinkedHashMap<>();
299	        Map<String, Integer> added = new HashMap<>();
300	        for (String name : jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY added", String.class,
301	                sheetId)) {
302	            added.put(name, added.size());
303	        }
304	        for (String name : jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY name", String.class,
305	                sheetId)) {
306	            members.put(name, new ArrayList<>());
307	        }
308	        Map<String, String> parents = new HashMap<>();
309	        jdbc.query("SELECT m.pool_name, m.person_id, m.member_pool, p.name, m.share, p.retired_from, m.from_date,"
310	                + " m.to_date, (m.from_date IS NULL OR m.from_date <= COALESCE(s.today, CURRENT_DATE))"
311	                + " AND (m.to_date IS NULL OR m.to_date >= COALESCE(s.today, CURRENT_DATE)) AS is_current"
312	                + " FROM pool_member m JOIN sheet s ON s.id = m.sheet_id"
313	                + " LEFT JOIN person p ON p.id = m.person_id WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
314	            List<PoolMember> of = members.get(rs.getString("pool_name"));
315	            if (of == null) return;
316	            String share = rs.getBigDecimal("share").setScale(2).toPlainString();
317	            String memberPool = rs.getString("member_pool");
318	            java.sql.Date fromDate = rs.getDate("from_date");
319	            java.sql.Date toDate = rs.getDate("to_date");
320	            String from = fromDate == null ? null : fromDate.toLocalDate().toString();
321	            String to = toDate == null ? null : toDate.toLocalDate().toString();
322	            boolean current = rs.getBoolean("is_current");
323	            if (memberPool != null) {
324	                parents.put(memberPool, rs.getString("pool_name"));
325	                of.add(new PoolMember(null, memberPool, memberPool, share, false, null, from, to, current));
326	            } else if (rs.getString("name") != null) {
327	                of.add(new PoolMember(rs.getLong("person_id"), null, rs.getString("name"), share,
328	                        rs.getDate("retired_from") != null, null, from, to, current));
329	            }
330	        }, sheetId);
331	        BigDecimal sheetPot = pot(sheetId);
332	        Set<Long> held = heldToday(sheetId);
333	        Map<String, Pool> done = new HashMap<>();
334	        List<Pool> pools = new ArrayList<>();
335	        for (String name : members.keySet()) {
336	            pools.add(resolve(name, members, parents, sheetPot, held, done).withAdded(added.get(name)));
337	        }
338	        return pools;
339	    }
