341	    /** The named pool with its cuts, resolving the pool above it first for its pot. */
342	    private static Pool resolve(String name, Map<String, List<PoolMember>> members, Map<String, String> parents,
343	            BigDecimal sheetPot, Set<Long> held, Map<String, Pool> done) {
344	        Pool known = done.get(name);
345	        if (known != null) return known;
346	        BigDecimal pot = sheetPot;
347	        String parent = parents.get(name);
348	        if (parent != null) {
349	            pot = null;
350	            if (members.containsKey(parent)) {
351	                for (PoolMember m : resolve(parent, members, parents, sheetPot, held, done).members()) {
352	                    if (name.equals(m.pool()) && m.cut() != null) pot = new BigDecimal(m.cut());
353	                }
354	            }
355	        }
356	        List<PoolMember> of = members.get(name);
357	        BigDecimal total = of.stream().filter(PoolMember::current).map(m -> new BigDecimal(m.share()))
358	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
359	        boolean balanced = total.compareTo(HUNDRED) == 0;
360	        boolean allRetired = of.stream().filter(PoolMember::current).allMatch(PoolMember::retired);
361	        Pool pool = new Pool(name, balanced && pot != null && !allRetired ? cut(of, pot, held) : of,
362	                total.toPlainString(), balanced, 0);
363	        done.put(name, pool);
364	        return pool;
365	    }
366	}
