722	    name      VARCHAR(500) NOT NULL,
723	    lead_id   BIGINT       NOT NULL,
724	    UNIQUE (sheet_id, name)
725	);
726	-- A crew's members: people of the sheet (at most once per crew, never its lead), listed in the order they were added (by id).
727	CREATE TABLE crew_member (
