-- A sheet's crews: a name (unique on the sheet, trimmed, not blank) and a lead, one of the sheet's people.
CREATE TABLE crew (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(500) NOT NULL,
    lead_id   BIGINT       NOT NULL,
    UNIQUE (sheet_id, name)
);
-- A crew's members: people of the sheet (at most once per crew, never its lead), listed in the order they were added (by id).
CREATE TABLE crew_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    crew_name VARCHAR(500) NOT NULL,
    person_id BIGINT       NOT NULL,
    UNIQUE (sheet_id, crew_name, person_id)
);
-- A sheet's pools: a name (unique on the sheet, trimmed, not blank).
CREATE TABLE pool (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(500) NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A pool's members: a person on the sheet (at most once per pool) with a share percent (more than 0.00,
-- at most 100.00, two decimals), listed in the order they were added (by id). A retired member's share
-- counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    pool_name VARCHAR(500)  NOT NULL,
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
    UNIQUE (sheet_id, pool_name, person_id)
);
-- A pool's member may instead be another pool of the sheet (member_pool, person_id then null), with a share
-- like a person's. A pool is a member of at most one pool, never of itself through any chain, and a chain of
-- pools is at most three deep. A pool that is a member of another shares out its cut in that pool, not the
-- sheet's pot.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool VARCHAR(500);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_pool_once UNIQUE (sheet_id, member_pool);
-- A pool membership may carry a from-date and a to-date (each optional; to on or after from). A member whose
-- dates do not include the sheet's today is left out of the pool: not in its total share, nor its balance, no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- A pool's place in the order pools were added to the sheet (from a sequence; a cloned sheet keeps its source's order).
CREATE SEQUENCE pool_added_seq;
ALTER TABLE pool ADD COLUMN added BIGINT DEFAULT NEXT VALUE FOR pool_added_seq;
UPDATE pool SET added = NEXT VALUE FOR pool_added_seq WHERE added IS NULL;
ALTER TABLE pool ALTER COLUMN added SET NOT NULL;

